import { afterEach, vi } from 'vitest';
import { POST } from '@/app/api/appointments/route';
import * as repo from '@/repos/appointments';

const REASON = 'zzdistinctivereasonzz';
const body = { practitionerId: 'pr_rosa', startsAt: '2030-01-01T10:00:00.000Z', endsAt: '2030-01-01T11:00:00.000Z', visitReason: REASON };

describe('POST /api/appointments', () => {
  afterEach(() => vi.restoreAllMocks());

  it('books and returns 201 with the id', async () => {
    const res = await call(POST, { method: 'POST', token: TOKENS.ava, body });
    expect(res.status).toBe(201);
    expect(res.json.id).toMatch(/^apt_/);
  });

  it('rejects a practitioner outside the care team', async () => {
    const res = await call(POST, { method: 'POST', token: TOKENS.ava, body: { ...body, practitionerId: 'pr_malik' } });
    expect(res.status).toBe(403);
  });

  it('on unexpected failure returns only an errorId and logs a PHI-free line', async () => {
    const err = Object.assign(new Error(`Duplicate entry 'ava@x' ${REASON}`), {
      code: 'ER_DUP_ENTRY',
      sql: `INSERT ... '${REASON}'`,
      sqlMessage: `Duplicate entry '${REASON}'`,
    });
    vi.spyOn(repo, 'createAppointment').mockRejectedValue(err);
    const out = vi.spyOn(process.stdout, 'write');
    const errw = vi.spyOn(process.stderr, 'write');
    const res = await call(POST, { method: 'POST', token: TOKENS.ava, body });
    expect(res.status).toBe(500);
    expect(res.json.errorId).toMatch(/^err_/);
    expect(Object.keys(res.json)).toEqual(['errorId']);
    const logged = [...out.mock.calls, ...errw.mock.calls].map((c) => String(c[0])).join('');
    expect(logged).toContain(res.json.errorId);
    expect(logged).toContain('POST /api/appointments');
    expect(logged).toContain('ER_DUP_ENTRY');
    expect(logged).not.toContain(REASON);
    expect(logged).not.toContain('ava@');
    expect(logged).not.toContain('INSERT');
  });
});
